// Tolerance is how far a delivery's webhook-timestamp may be from this
// server's clock before it is rejected as a possible replay.
const Tolerance = 300 * time.Second

// DedupCapacity is how many webhook-ids are remembered to drop
// redeliveries. Set it to 0 to turn deduplication off.
const DedupCapacity = 10000

// MaxBodyBytes caps the request body read before verification.
const MaxBodyBytes = 10 << 20

// UnknownEventStatus answers a verified delivery that no handler matches.
// A 4xx makes it fail visibly in Sparrow instead of being dropped.
const UnknownEventStatus = 422

// Config configures a Receiver.
type Config struct {
	// Secret is the webhook's signing secret (whsec_...). Never commit it.
	Secret string
	// Now returns the current time; nil means time.Now.
	Now func() time.Time
	// TestLog, when set, gets one JSON line per handler call
	// (SPARROW_RECEIVER_TEST_MODE=1 sets it to stdout).
	TestLog io.Writer
}

// ConfigFromEnv reads the configuration from the environment.
func ConfigFromEnv() (Config, error) {
	var cfg Config
	cfg.Secret = os.Getenv("SPARROW_WEBHOOK_SECRET")
	if cfg.Secret == "" {
		return cfg, errors.New("SPARROW_WEBHOOK_SECRET is not set")
	}
	if os.Getenv("SPARROW_RECEIVER_TEST_MODE") == "1" {
		cfg.TestLog = os.Stdout
	}
	return cfg, nil
}

