	rc := &Receiver{
		cfg:      cfg,
		verifier: signature.Verifier{Tolerance: Tolerance, Now: now},
		seen:     newDedup(DedupCapacity),
		mux:      http.NewServeMux(),
	}
	rc.mux.HandleFunc("POST /webhook", rc.handleWebhook)
	rc.mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
