// DecodeError is a body that does not match the handler's model; it is
// answered with 400.
type DecodeError struct{ Err error }

func (e *DecodeError) Error() string { return fmt.Sprintf("decode body: %v", e.Err) }
func (e *DecodeError) Unwrap() error { return e.Err }

// record writes one test-mode line per handler call.
func (rc *Receiver) record(handler, subscriptionID, eventType string, d delivery, value any) {
	if rc.cfg.TestLog == nil {
		return
	}
	line, err := json.Marshal(map[string]any{
		"handler":         handler,
		"subscription_id": subscriptionID,
		"event_type":      eventType,
		"webhook_id":      d.MessageID,
		"value":           value,
	})
	if err != nil {
		return
	}
	rc.logMu.Lock()
	defer rc.logMu.Unlock()
	_, _ = rc.cfg.TestLog.Write(append(line, '\n'))
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// dedup is an in-memory LRU of seen webhook-ids. It is per process and lost
// on restart: with several instances, use a shared store (your database)
// instead.
type dedup struct {
	mu    sync.Mutex
	cap   int
	order *list.List
	items map[string]*list.Element
}

func newDedup(capacity int) *dedup {
	return &dedup{cap: capacity, order: list.New(), items: map[string]*list.Element{}}
}

func (d *dedup) Has(id string) bool {
	d.mu.Lock()
	defer d.mu.Unlock()
	_, ok := d.items[id]
	return ok
}

func (d *dedup) Add(id string) {
	if d.cap <= 0 || id == "" {
		return
	}
	d.mu.Lock()
	defer d.mu.Unlock()
	if el, ok := d.items[id]; ok {
		d.order.MoveToFront(el)
		return
	}
	d.items[id] = d.order.PushFront(id)
	if d.order.Len() > d.cap {
		oldest := d.order.Back()
		d.order.Remove(oldest)
		delete(d.items, oldest.Value.(string))
	}
}
